@@ -85,5 +85,31 @@ describe("a deploy alone", () => {
     expect(rebuiltOnly({ ...base, sha: "b", previous_sha: null })).toBe(true);
     expect(rebuiltOnly({ ...base, sha: "b", previous_sha: "a" })).toBe(false);
